CREATE TABLE IF NOT EXISTS wip_orders (issue_id TEXT PRIMARY KEY, issue_key TEXT NOT NULL, project_key TEXT, region TEXT, entity TEXT, summary TEXT, org TEXT, status TEXT, status_cat TEXT, created TEXT, done_at TEXT, updated TEXT, upfront REAL, quote_no TEXT, labels TEXT, customer_item INTEGER NOT NULL DEFAULT 0, has_doc INTEGER NOT NULL DEFAULT 0, doc_yes INTEGER NOT NULL DEFAULT 0, legacy INTEGER NOT NULL DEFAULT 1, division_jira TEXT, progress REAL, non_admin REAL, children INTEGER, open_work INTEGER, invoiced REAL, paid REAL, token_qty REAL, token_only INTEGER NOT NULL DEFAULT 0, token_paid INTEGER NOT NULL DEFAULT 0, move_sig TEXT, computed_at TEXT, seen_at TEXT, gone INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_wip_orders_key ON wip_orders(issue_key);
CREATE TABLE IF NOT EXISTS wip_items (issue_id TEXT PRIMARY KEY, issue_key TEXT, order_id TEXT NOT NULL, parent_id TEXT, level INTEGER NOT NULL, issuetype TEXT, subtask INTEGER NOT NULL DEFAULT 0, status TEXT, status_cat TEXT, summary TEXT, share REAL, inv_due TEXT, inv_date TEXT, division TEXT, created TEXT);
CREATE INDEX IF NOT EXISTS idx_wip_items_order ON wip_items(order_id);
CREATE TABLE IF NOT EXISTS wip_contracts (issue_id TEXT PRIMARY KEY, issue_key TEXT NOT NULL, project_key TEXT, region TEXT, summary TEXT, org TEXT, status TEXT, status_cat TEXT, start_date TEXT, end_date TEXT, ended_at TEXT, total REAL, steps INTEGER, steps_invoiced INTEGER, steps_paid INTEGER, seen_at TEXT, gone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wip_seed (issue_key TEXT PRIMARY KEY, kind TEXT NOT NULL, region TEXT, division TEXT, upfront REAL, upfront_text TEXT, quote_no TEXT, accepted TEXT, start_date TEXT, end_date TEXT, title TEXT, org TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS wip_overrides (issue_key TEXT PRIMARY KEY, division TEXT, upfront REAL, excluded INTEGER NOT NULL DEFAULT 0, note TEXT, updated_by TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS wip_snapshots (month TEXT NOT NULL, issue_key TEXT NOT NULL, region TEXT NOT NULL, org TEXT, title TEXT, status TEXT, division TEXT, upfront REAL, token INTEGER NOT NULL DEFAULT 0, quote_no TEXT, accepted TEXT, done_at TEXT, progress REAL, non_admin REAL, invoiced REAL, paid REAL, source TEXT, PRIMARY KEY (month, issue_key));
CREATE INDEX IF NOT EXISTS idx_wip_snapshots_region ON wip_snapshots(region, month);
CREATE TABLE IF NOT EXISTS wip_history (month TEXT NOT NULL, region TEXT NOT NULL, data TEXT NOT NULL, source TEXT, PRIMARY KEY (month, region));
CREATE TABLE IF NOT EXISTS wip_moves (issue_key TEXT PRIMARY KEY, issue_id TEXT, target TEXT NOT NULL, from_status TEXT, reason TEXT, status TEXT NOT NULL DEFAULT 'pending', tries INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0, last_error TEXT, queued_at TEXT, done_at TEXT);
